/* The Azerbaijani text is the key; {0}, {1} in a translation stand for the template's values in source order. */
function TX(strs, ...vals) {
  const key = strs.join('{}'), dict = I18N[LANG];
  if (dict && dict[key] !== undefined) return dict[key].replace(/\{(\d)\}/g, (_, i) => vals[+i]);
  if (dict) TX.missing.add(key);
  return strs.reduce((a, s, i) => a + vals[i - 1] + s);
}
